// ---- Import prototype helpers ----
const SITE_I=(act,o={})=>({av:"AB",avFill:"#D97706",title:"Acme Bakery",subtitle:"Acme Ltd · acmebakery.ie",role:o.role,
 sections:o.owner?[STRUCT_SECTIONS()[0]]:[STRUCT_SECTIONS()[0],{...STRUCT_SECTIONS()[1],items:[...STRUCT_SECTIONS()[1].items,["download","Import"]]}],
 footer:[["settings","Site settings"]],active:act});
function shellI(name,i,act,crumbsArr,o={}){const r=screen(name,(i%3)*1540,Math.floor(i/3)*1000,{w:1440,h:900});sidebarA(r,SITE_I(act,o));const m=mainCol(r);topbarA(m,["Acme Ltd","Acme Bakery",...crumbsArr]);return {r,m};}
const STEPS=["Source","Map","Preview","Run","Report"];
function stepper(p,active){const s=fr(p,"Stepper",{gap:6,alignItems:"center"});STEPS.forEach((l,i)=>{const a=STEPS.indexOf(active);const done=i<a,cur=i==a;if(i)fr(s,"Line",{width:24,height:1,fill:done||cur?"$primary":"$border"});const st=fr(s,"Step "+l,{gap:6,alignItems:"center"});const d=fr(st,"Dot",{width:20,height:20,cornerRadius:999,alignItems:"center",justifyContent:"center",...(done?{fill:"$primary"}:cur?{stroke:"$primary",strokeWidth:2,fill:"$bg"}:{stroke:"$border",strokeWidth:1,fill:"$bg"})});if(done)ic(d,"check",{width:12,height:12,fill:"$primary-fg"});else tx(d,String(i+1),{fontSize:11,fontWeight:"600",fill:cur?"$primary":"$muted-fg"});tx(st,l,{fontSize:12,fontWeight:cur?"600":"500",fill:cur||done?"$fg":"$muted-fg"});});return s;}
function wizHead(m,title,sub,active,o={}){const h=fr(m,"Import header",{width:"fill_container",padding:[18,32,16,32],gap:16,alignItems:"center",stroke:"$border",strokeWidth:{bottom:1}});btn(h,null,{icon:"arrow-left",kind:"ghost"});const t=fr(h,"T",{layout:"vertical",gap:2});tx(t,title,{fontSize:17,fontWeight:"600"});tx(t,sub,{fontSize:12,fill:"$muted-fg"});sp(h);stepper(h,active);sp(h);for(const b of (o.btns||[]))btn(h,b[0],b[1]||{});return h;}
function sel(p,v,o={}){const s=input(p,v,{value:!o.ph,trail:"chevron-down",width:o.width,icon:o.icon});if(o.tag){}return s;}
function bar(p,frac,o={}){const b=fr(p,"Progress",{width:o.w||"fill_container",height:o.h||6,cornerRadius:999,fill:"$muted",clip:true,layout:"horizontal"});if(frac>0)fr(b,"Fill",{width:Math.max(4,Math.round((o.px||300)*frac)),height:"fill_container",cornerRadius:999,fill:o.fill||"$primary"});return b;}
function tbl(p,W,hdr,rows,o={}){const t=fr(p,o.name||"Table",{layout:"vertical",width:o.w||"fill_container",cornerRadius:8,stroke:"$border",strokeWidth:1,clip:true,fill:"$bg"});const mk=(cells,h,ri)=>{const sel=!h&&o.sel===ri;const r=fr(t,h?"Header row":"Row "+ri,{width:"fill_container",height:h?36:(o.rh||44),padding:[0,14],gap:12,alignItems:"center",...(h?{fill:"$muted"}:{stroke:"$border",strokeWidth:{top:1}}),...(sel?{fill:"$accent"}:{}),...(o.dim&&o.dim.includes(ri)?{opacity:0.55}:{})});cells.forEach((c,i)=>{const cell=fr(r,"Cell",{width:W[i],alignItems:"center",gap:6});if(typeof c=="function")c(cell);else tx(cell,String(c),h?{fontSize:12,fontWeight:"500",fill:"$muted-fg"}:{textGrowth:"fixed-width",width:"fill_container"});});};mk(hdr,true);rows.forEach((r,i)=>mk(r,false,i));return t;}
function stat(p,n,l,o={}){const c=fr(p,"Stat "+l,{layout:"vertical",gap:4,width:"fill_container",padding:[14,16],cornerRadius:10,stroke:o.stroke||"$border",strokeWidth:1,fill:o.fill||"$bg"});const h=fr(c,"h",{gap:6,alignItems:"center"});ic(h,o.icon||"circle",{width:14,height:14,fill:o.c||"$muted-fg"});tx(h,l,{fontSize:12,fill:"$muted-fg",fontWeight:"500"});tx(c,n,{fontSize:22,fontWeight:"600",fill:o.c||"$fg"});if(o.sub)tx(c,o.sub,{fontSize:11,fill:"$muted-fg"});return c;}
function warnNote(p,t,o={}){const n=fr(p,"Warn",{width:o.w||"fill_container",padding:[8,10],gap:8,cornerRadius:8,fill:"$warn-bg",alignItems:"start"});ic(n,o.icon||"triangle-alert",{width:14,height:14,fill:"$warn"});tx(n,t,{fontSize:12,fill:"$warn",textGrowth:"fixed-width",width:"fill_container",lineHeight:1.4});return n;}
function arrow(p){return ic(p,"arrow-right",{width:14,height:14});}
function typeIc(p,i){const b=fr(p,"TI",{width:26,height:26,cornerRadius:6,fill:"$muted",alignItems:"center",justifyContent:"center"});ic(b,i,{width:14,height:14,fill:"$fg"});return b;}
function small(p,t,o={}){return tx(p,t,{fontSize:12,fill:"$muted-fg",...o});}
